questionvariables.text:
/* choose a random solution for x */
soln_x: 2 + rand_with_step(1,5,1); /* integer x between 1 and 10 */
ta1: soln_x; 

/* coefficients */
var1: rand_with_step(5,20,1); 
var2: rand_with_step(5,20,1); 

/* build expressions so they match */
angl_corres_1: var1*x + 5;
/* define var3 so equality holds exactly when x=soln_x */
var3: var2*soln_x - (var1*soln_x + 5);
angl_corres_2: var2*x - var3;

/* actual angle values when x=soln_x */
angl_BO_1Y: decimalplaces(float(subst(x=soln_x, angl_corres_1)),2);
angl_DO_2O_1: decimalplaces(float(subst(x=soln_x, angl_corres_2)),2);

/* Solutions of the actual angles */
angl_corres_11: var1*soln_x + 5;
angl_corres_22: var2*soln_x  - var3;

angl_AO1O2: angl_corres_11;          /* vertical opposite with ∠BO1Y */ 
angl_CO2X: angl_corres_22;           /* vertical opposite with ∠DO2O1 */ 
angl_O2O1B: 180 - angl_corres_11;    /* linear pair with ∠BO1Y */ 
angl_XO2B:  180 - angl_corres_22;    /* linear pair with ∠DO2O1 */
